// ---------------------------------------------------------------------------
// WorkSense Phase 8 onboarding engine — fully deterministic, zero LLM.
//  - Task definition vs execution state (separate column groups)
//  - Strict owner matrix: employee | manager | hr | it_security (no broad HR
//    to service owners)
//  - DAG planning from the APPROVED role relationship (application ->
//    requisition), never a title substring
//  - Cycle / missing-dep validation + Kahn topological scheduling
//  - Blocked set (multiple simultaneous blockers) + critical path
//  - Honest readiness estimate (never a guarantee)
//  - plan_hash bound to canonical task definitions (approvals bind to it)
//  - Waiver, adaptation (learning -> verification, failed verification reopens
//    gap), completion checks as PURE functions so backend functions just
//    load rows and apply them.
// ---------------------------------------------------------------------------

export type OwnerRole = "employee" | "manager" | "hr" | "it_security";
export type TaskType = "learning" | "verification" | "provisioning" | "policy" | "access" | "onboarding_admin";
export type TaskState = "pending" | "blocked" | "ready" | "in_progress" | "done" | "waived" | "failed";
export type PlanStatus = "draft" | "pending_approval" | "approved" | "completed" | "superseded";

export interface WhyEvidence {
  reason: string;
  source_evidence: { source_type: string; fact: string; ref?: string }[];
}

export interface EvReq {
  kind: "note" | "assessment_id";
  label: string;
  required: boolean;
}

/** Immutable task DEFINITION — what needs to happen. */
export interface TaskDef {
  task_code: string;
  title: string;
  task_type: TaskType;
  owner_role: OwnerRole;
  required: boolean;
  non_waivable: boolean;
  depends_on: string[];
  duration_days: number;
  why_evidence: WhyEvidence;
  evidence_requirements: EvReq[];
}

export interface Blocker {
  id: string;
  note: string;
  reported_by: string;
  at: string;
  status: "open" | "resolved";
  resolved_by?: string;
  resolved_at?: string;
}

export interface Waiver {
  by_twin_id: string;
  by_name: string;
  reason: string;
  policy_basis: { doc_code: string; version: number | null } | null;
  at: string;
}

export interface CompletionRecord {
  actor_twin_id: string;
  actor_name: string;
  at: string;
  evidence: { kind: "note" | "assessment_id"; label: string; value: string }[];
  attempt_hash: string;
  note?: string;
}

export interface Adaptation {
  kind: "replaced" | "reopened_gap";
  replaced_by?: string;
  reason: string;
  source_evidence: WhyEvidence["source_evidence"];
  at: string;
  actor_twin_id: string;
}

/** Task DEFINITION + EXECUTION state. */
export interface PlanTask extends TaskDef {
  state: TaskState;
  start_date: string | null;
  due_date: string | null;
  topological_level: number;
  blocked_reasons: string[]; // task_codes of unmet deps
  blockers: Blocker[];
  waiver: Waiver | null;
  completion_record: CompletionRecord | null;
  adaptation: Adaptation | null;
}

export interface ReadinessDimension {
  key: "access" | "compliance" | "capability";
  label: string;
  /** satisfied = done (or waived for access/compliance; waived NEVER counts as
   *  capability — a waived task must not imply a skill was verified). */
  satisfied: number;
  total: number;
  pct: number;
  note: string;
}

export interface ReadinessEstimate {
  /** Overall task completion (done + waived). */
  ready_pct: number;
  satisfied: number;
  total: number;
  /** Remaining critical path, in duration-days (not node count). */
  remaining_critical_days: number;
  /** Business-day projection from today; null when blockers make it unknown. */
  projected_ready_date: string | null;
  blocked_count: number;
  note: string;
  /** True when the projection is provisional (open blockers on the path). */
  provisional: boolean;
  /** Remaining critical path as task codes (ordered, by duration). */
  critical_path: string[];
  /** Access / compliance / role-capability readiness shown separately from
   *  overall completion. */
  dimensions: ReadinessDimension[];
  working_calendar: "business_days";
}

export interface CarryoverEntry {
  task_code: string;
  from_version: number;
  from_plan_id: string;
  note: string;
}

export class CycleError extends Error {
  constructor(message = "cyclic dependency detected in onboarding plan") {
    super(message);
    this.name = "CycleError";
  }
}

// ---------------------------------------------------------------------------
// Hashing (deterministic, sync; binding approval to exact task definitions)
// ---------------------------------------------------------------------------

function fnv1a(str: string, seed = 0x811c9dc5): number {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** Stable hash of canonical task definitions — same defs always hash equal. */
export function planHash(defs: TaskDef[]): string {
  const canonical = defs
    .map((d) =>
      JSON.stringify({
        code: d.task_code,
        title: d.title,
        type: d.task_type,
        owner: d.owner_role,
        required: d.required,
        non_waivable: d.non_waivable,
        deps: [...d.depends_on].sort(),
        days: d.duration_days,
        why: d.why_evidence,
        evreq: d.evidence_requirements,
      })
    )
    .sort()
    .join("\u0001");
  const h1 = fnv1a(canonical).toString(16).padStart(8, "0");
  const h2 = fnv1a(canonical, 0x811c9dc5 ^ canonical.length).toString(16).padStart(8, "0");
  return `${h1}${h2}`;
}

/** Attempt hash for execution dedup: same actor+payload on same task+action. */
export function attemptHash(planId: string, taskCode: string, action: string, payload: unknown): string {
  const canonical = JSON.stringify({ planId, taskCode, action, payload });
  const h1 = fnv1a(canonical).toString(16).padStart(8, "0");
  const h2 = fnv1a(canonical, 0xdeadbeef).toString(16).padStart(8, "0");
  return `${h1}${h2}`;
}

// ---------------------------------------------------------------------------
// DAG validation + topological scheduling
// ---------------------------------------------------------------------------

export function validateDag(defs: TaskDef[]): void {
  const ids = new Set(defs.map((d) => d.task_code));
  for (const d of defs) {
    for (const dep of d.depends_on) {
      if (!ids.has(dep)) throw new Error(`task ${d.task_code} depends on unknown task ${dep}`);
    }
  }
  const indegree = new Map(defs.map((d) => [d.task_code, d.depends_on.length]));
  const adj = new Map<string, string[]>();
  for (const d of defs) {
    for (const dep of d.depends_on) adj.set(dep, [...(adj.get(dep) ?? []), d.task_code]);
  }
  const queue = defs.filter((d) => (indegree.get(d.task_code) ?? 0) === 0).map((d) => d.task_code);
  const order: string[] = [];
  while (queue.length > 0) {
    const id = queue.shift()!;
    order.push(id);
    for (const child of adj.get(id) ?? []) {
      indegree.set(child, (indegree.get(child) ?? 0) - 1);
      if ((indegree.get(child) ?? 0) === 0) queue.push(child);
    }
  }
  if (order.length !== defs.length) throw new CycleError();
}

const DAY_MS = 24 * 60 * 60 * 1000;
function addDays(d: Date, days: number): Date {
  return new Date(d.getTime() + days * DAY_MS);
}

export function topologicalOrder(defs: TaskDef[]): string[] {
  validateDag(defs);
  const indegree = new Map(defs.map((d) => [d.task_code, d.depends_on.length]));
  const adj = new Map<string, string[]>();
  for (const d of defs) {
    for (const dep of d.depends_on) adj.set(dep, [...(adj.get(dep) ?? []), d.task_code]);
  }
  const queue = defs.filter((d) => (indegree.get(d.task_code) ?? 0) === 0).map((d) => d.task_code);
  const order: string[] = [];
  while (queue.length > 0) {
    const id = queue.shift()!;
    order.push(id);
    for (const child of adj.get(id) ?? []) {
      indegree.set(child, (indegree.get(child) ?? 0) - 1);
      if ((indegree.get(child) ?? 0) === 0) queue.push(child);
    }
  }
  return order;
}

/** Satisfied = done or waived. Used for both state derivation and critical path. */
export function satisfiedSet(tasks: Pick<PlanTask, "task_code" | "state">[]): Set<string> {
  return new Set(tasks.filter((t) => t.state === "done" || t.state === "waived").map((t) => t.task_code));
}

export function hasOpenBlocker(blockers: Blocker[]): boolean {
  return blockers.some((b) => b.status === "open");
}

/**
 * Recompute execution state + dates from stored facts (definition + state).
 * Dates are null for blocked/failed tasks and cascade downstream.
 */
export function deriveStates(defs: TaskDef[], facts: {
  done?: string[];
  waived?: string[];
  failed?: string[];
  blockers?: Record<string, Blocker[]>;
  approved?: boolean;
  startDate?: string;
}): PlanTask[] {
  validateDag(defs);
  const done = new Set(facts.done ?? []);
  const waived = new Set(facts.waived ?? []);
  const failed = new Set(facts.failed ?? []);
  const approved = facts.approved ?? false;
  const start = facts.startDate ? new Date(facts.startDate) : new Date();

  const order = topologicalOrder(defs);
  const defById = new Map(defs.map((d) => [d.task_code, d]));

  const level = new Map<string, number>();
  for (const id of order) {
    const d = defById.get(id)!;
    level.set(id, d.depends_on.reduce((m, dep) => Math.max(m, (level.get(dep) ?? 0) + 1), 0));
  }

  const endBy = new Map<string, Date | null>();
  const out = new Map<string, PlanTask>();
  for (const id of order) {
    const d = defById.get(id)!;
    const blockers = facts.blockers?.[id] ?? [];
    const open = hasOpenBlocker(blockers);
    const depStates = new Map(d.depends_on.map((dep) => [dep, out.get(dep)?.state ?? "missing"]));
    const unmet = d.depends_on.filter((dep) => !done.has(dep) && !waived.has(dep));
    const cascadingBlock = d.depends_on.some((dep) => {
      const s = depStates.get(dep);
      return s === "blocked" || s === "failed";
    });

    let state: TaskState = "pending";
    if (done.has(id)) state = "done";
    else if (waived.has(id)) state = "waived";
    else if (failed.has(id)) state = "failed";
    else if (!approved) state = "pending";
    else if (open) state = "blocked";
    else if (cascadingBlock) state = "blocked";
    else if (unmet.length > 0) state = "pending"; // queued: approved but deps not yet satisfied
    else state = "ready";

    let startDate: Date | null;
    let endDate: Date | null;
    if (state === "blocked" || state === "failed") {
      startDate = null;
      endDate = null;
    } else {
      const prereqEnds = d.depends_on
        .map((dep) => endBy.get(dep))
        .filter((e): e is Date => e instanceof Date);
      const base = prereqEnds.length > 0 ? new Date(Math.max(...prereqEnds.map((e) => e.getTime()))) : new Date(start);
      startDate = base;
      endDate = addDays(base, d.duration_days);
    }
    endBy.set(id, endDate);

    out.set(id, {
      ...d,
      state,
      start_date: startDate ? startDate.toISOString() : null,
      due_date: endDate ? endDate.toISOString() : null,
      topological_level: level.get(id) ?? 0,
      blocked_reasons: unmet,
      blockers,
      waiver: null,
      completion_record: null,
      adaptation: null,
    });
  }
  return [...out.values()];
}

/** Apply stored execution records onto derived states (single source of truth). */
export function materialize(tasks: PlanTask[], records: {
  completion?: Record<string, CompletionRecord>;
  waiver?: Record<string, Waiver>;
  adaptation?: Record<string, Adaptation>;
  blockers?: Record<string, Blocker[]>;
}): PlanTask[] {
  return tasks.map((t) => ({
    ...t,
    state: records.waiver?.[t.task_code]
      ? "waived"
      : records.completion?.[t.task_code]
        ? "done"
        : records.adaptation?.[t.task_code]
          ? "failed"
          : t.state,
    blockers: records.blockers?.[t.task_code] ?? t.blockers,
    waiver: records.waiver?.[t.task_code] ?? t.waiver,
    completion_record: records.completion?.[t.task_code] ?? t.completion_record,
    adaptation: records.adaptation?.[t.task_code] ?? t.adaptation,
  }));
}

// ---------------------------------------------------------------------------
// Critical path + honest readiness estimate
// ---------------------------------------------------------------------------

/** Longest remaining chain (by duration) among tasks that are not satisfied. */
export function criticalPath(defs: TaskDef[], satisfied: Set<string>): { tasks: string[]; total_days: number } {
  validateDag(defs);
  const defById = new Map(defs.map((d) => [d.task_code, d]));
  const adj = new Map<string, string[]>();
  for (const d of defs) for (const dep of d.depends_on) adj.set(dep, [...(adj.get(dep) ?? []), d.task_code]);

  const memo = new Map<string, { tasks: string[]; days: number }>();
  const chainFrom = (id: string): { tasks: string[]; days: number } => {
    const known = memo.get(id);
    if (known) return known;
    const d = defById.get(id)!;
    let best: { tasks: string[]; days: number } = { tasks: [], days: 0 };
    for (const child of adj.get(id) ?? []) {
      const c = chainFrom(child);
      if (c.days > best.days) best = c;
    }
    const res = { tasks: [id, ...best.tasks], days: d.duration_days + best.days };
    memo.set(id, res);
    return res;
  };

  let best: { tasks: string[]; days: number } = { tasks: [], days: 0 };
  for (const d of defs) {
    if (satisfied.has(d.task_code)) continue;
    const c = chainFrom(d.task_code);
    if (c.days > best.days) best = c;
  }
  return { tasks: best.tasks, total_days: best.days };
}

/** Business-day calendar: duration days map onto working days only. */
function addBusinessDays(start: Date, workingDays: number): Date {
  const d = new Date(start);
  let remaining = workingDays;
  while (remaining > 0) {
    d.setUTCDate(d.getUTCDate() + 1);
    const dow = d.getUTCDay();
    if (dow === 0 || dow === 6) continue; // weekend
    remaining -= 1;
  }
  return d;
}

/**
 * Honest readiness: overall task completion shown SEPARATELY from access,
 * compliance and role-capability readiness. The critical path uses remaining
 * durations (business days) over prerequisites — never the longest node chain.
 * Blockers on the path make the projection provisional (unknown date); waived
 * learning/verification tasks never count as capability.
 */
export function estimateReadiness(defs: TaskDef[], tasks: PlanTask[], startDate: string, now: string): ReadinessEstimate {
  const satisfied = satisfiedSet(tasks);
  const total = defs.length;
  const readyPct = total === 0 ? 0 : Math.round((satisfied.size / total) * 1000) / 10;
  const { tasks: path, total_days } = criticalPath(defs, satisfied);
  const blockedCount = tasks.filter((t) => t.state === "blocked" || t.state === "failed").length;

  // A blocker on any remaining critical-path task means the date is unknown,
  // not confidently projected — label the estimate provisional (spec: forecast
  // dates must account for blockers; label provisional estimates).
  const openOnPath = path.filter((code) => tasks.find((t) => t.task_code === code)?.blockers.some((b) => b.status === "open"));
  const provisional = openOnPath.length > 0;
  const projected = total_days === 0 ? null : provisional ? null : addBusinessDays(new Date(now), total_days).toISOString();

  const dimensionFor = (key: ReadinessDimension["key"], types: TaskType[], countWaived: boolean): ReadinessDimension => {
    const members = tasks.filter((t) => types.includes(t.task_type));
    const sat = members.filter((t) => t.state === "done" || (countWaived && t.state === "waived")).length;
    const pct = members.length === 0 ? 100 : Math.round((sat / members.length) * 1000) / 10;
    return {
      key,
      label: key === "access" ? "Access readiness" : key === "compliance" ? "Compliance readiness" : "Role capability",
      satisfied: sat,
      total: members.length,
      pct,
      note:
        key === "capability"
          ? "Waived tasks never count as verified skill — capability needs a completed learning or verification task."
          : key === "access"
            ? "Provisioning and system-access tasks complete the technical floor."
            : "Mandatory policy tasks are done before systems stay open.",
    };
  };

  const dimensions: ReadinessDimension[] = [
    dimensionFor("access", ["provisioning", "access"], true),
    dimensionFor("compliance", ["policy"], true),
    dimensionFor("capability", ["learning", "verification"], false),
  ];

  const note = provisional
    ? `Estimated readiness — ${openOnPath.length} blocker(s) remain on the critical path, so the ready date is unknown until they clear. Blocked work makes this provisional, not a guarantee.`
    : "Estimated readiness — projected earliest completion in business days from today; an estimate, not a guarantee.";

  return {
    ready_pct: readyPct,
    satisfied: satisfied.size,
    total,
    remaining_critical_days: total_days,
    projected_ready_date: projected,
    blocked_count: blockedCount,
    note,
    provisional,
    critical_path: path,
    dimensions,
    working_calendar: "business_days",
  };
}

// ---------------------------------------------------------------------------
// Authorization matrix — strict per-owner-role, no broad HR to service owners
// ---------------------------------------------------------------------------

export function canActOnTask(actor: { id: string; role: string; org_id: string | null }, taskOwner: OwnerRole, twin: { id: string; manager_id: string | null; org_id: string | null }): { ok: boolean; error?: string } {
  if (actor.org_id !== twin.org_id) return { ok: false, error: "Cross-org task access is forbidden." };
  switch (taskOwner) {
    case "employee":
      return actor.id === twin.id
        ? { ok: true }
        : { ok: false, error: "Only the employee themselves may complete this task." };
    case "manager":
      return actor.role === "manager" && actor.id === twin.manager_id
        ? { ok: true }
        : { ok: false, error: "Only the employee's direct manager may act on this task." };
    case "hr":
      return actor.role === "hr_executive" || actor.role === "hr_partner"
        ? { ok: true }
        : { ok: false, error: "Only HR may act on this task." };
    case "it_security":
      return actor.role === "it_security"
        ? { ok: true }
        : { ok: false, error: "Only the IT security service owner may act on this task — HR has no access to service-owner tasks." };
    default:
      return { ok: false, error: "Unknown owner role." };
  }
}

export function canWaive(actor: { id: string; role: string }, twin: { manager_id: string | null }, taskNonWaivable: boolean, taskOwner: OwnerRole): { ok: boolean; error?: string } {
  if (taskNonWaivable) {
    return actor.role === "hr_executive"
      ? { ok: true }
      : { ok: false, error: "Non-waivable tasks may only be waived by an HR Executive with a policy basis." };
  }
  if (actor.role === "manager" && actor.id === twin.manager_id) return { ok: true };
  if (actor.role === "hr_executive" || actor.role === "hr_partner") return { ok: true };
  return { ok: false, error: "Waivers require the employee's manager or an HR role." };
}

export function canAdapt(actor: { id: string; role: string }, twin: { manager_id: string | null }): { ok: boolean; error?: string } {
  if (actor.role === "manager" && actor.id === twin.manager_id) return { ok: true };
  if (actor.role === "hr_executive" || actor.role === "hr_partner") return { ok: true };
  return { ok: false, error: "Plan adaptation requires the employee's manager or an HR role." };
}

// ---------------------------------------------------------------------------
// Completion checks — pure; every gate the backend must enforce
// ---------------------------------------------------------------------------

export interface CompletionCheckInput {
  planStatus: PlanStatus;
  task: PlanTask;
  actor: { id: string; role: string; org_id: string | null };
  twin: { id: string; manager_id: string | null; org_id: string | null };
  evidence: { kind: "note" | "assessment_id"; label: string; value: string }[];
}

export function validateCompletion(i: CompletionCheckInput): { ok: boolean; code?: string; error?: string } {
  if (i.planStatus !== "approved") {
    return { ok: false, code: "plan_pending", error: "The plan must be approved by the Manager and HR Executive before tasks can be completed." };
  }
  const auth = canActOnTask(i.actor, i.task.owner_role, i.twin);
  if (!auth.ok) return { ok: false, code: "forbidden", error: auth.error };
  if (i.task.state === "done") {
    return { ok: false, code: "double_submission", error: `"${i.task.title}" is already complete — double submission rejected.` };
  }
  if (i.task.state === "waived") {
    return { ok: false, code: "already_waived", error: `"${i.task.title}" was waived — nothing to complete.` };
  }
  if (i.task.state === "failed") {
    return { ok: false, code: "task_failed", error: `"${i.task.title}" is failed/adopted out — regenerate the plan.` };
  }
  const open = i.task.blockers.filter((b) => b.status === "open");
  if (open.length > 0) {
    return { ok: false, code: "blocked", error: `Cannot complete — open blocker(s): ${open.map((b) => b.note).join("; ")}.` };
  }
  if (i.task.state === "blocked") {
    const why = i.task.blocked_reasons.length > 0 ? `Prerequisites not satisfied: ${i.task.blocked_reasons.join(", ")}` : "blocked by an upstream task or blocker";
    return { ok: false, code: "unmet_prerequisite", error: `Cannot complete — ${why}.` };
  }
  if (i.task.blocked_reasons.length > 0) {
    return { ok: false, code: "unmet_prerequisite", error: `Prerequisites not satisfied: ${i.task.blocked_reasons.join(", ")}.` };
  }
  if (i.task.state === "pending") {
    return { ok: false, code: "plan_pending", error: "The plan is not active yet." };
  }
  const missing = (i.task.evidence_requirements ?? []).filter((r) => r.required && !i.evidence.some((e) => e.kind === r.kind && String(e.value ?? "").trim().length > 0));
  if (missing.length > 0) {
    return { ok: false, code: "missing_evidence", error: `Evidence required before completion: ${missing.map((m) => m.label).join(", ")}.` };
  }
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Waiver application (authorized actor/reason/policy basis/audit)
// ---------------------------------------------------------------------------

export interface WaiverInput {
  by_twin_id: string;
  by_name: string;
  reason: string;
  policy_basis: { doc_code: string; version: number | null } | null;
  at: string;
}

export function applyWaiver(task: PlanTask, waiver: WaiverInput): PlanTask {
  return {
    ...task,
    state: "waived",
    waiver: { ...waiver },
    completion_record: null,
  };
}

// ---------------------------------------------------------------------------
// Adaptation: learning -> verification, and failed verification reopens gap
// ---------------------------------------------------------------------------

export interface AdaptationInput {
  actor_twin_id: string;
  reason: string;
  source_evidence: WhyEvidence["source_evidence"];
  at: string;
}

/** Replace a learning task with a verification task (new assessment evidence). */
export function adaptLearningToVerification(defs: TaskDef[], learningTask: TaskDef, verifyDef: TaskDef, input: AdaptationInput): { defs: TaskDef[]; adaptation: Adaptation } {
  const adaptation: Adaptation = {
    kind: "replaced",
    replaced_by: verifyDef.task_code,
    reason: input.reason,
    source_evidence: input.source_evidence,
    at: input.at,
    actor_twin_id: input.actor_twin_id,
  };
  const rest = defs.filter((d) => d.task_code !== learningTask.task_code);
  return { defs: [...rest, verifyDef], adaptation };
}

/** Mark a verification task failed: the gap reopens and the plan must revise. */
export function failVerification(task: PlanTask, input: AdaptationInput): { task: PlanTask; adaptation: Adaptation } {
  const adaptation: Adaptation = {
    kind: "reopened_gap",
    reason: input.reason,
    source_evidence: input.source_evidence,
    at: input.at,
    actor_twin_id: input.actor_twin_id,
  };
  return { task: { ...task, state: "failed", adaptation }, adaptation };
}

// ---------------------------------------------------------------------------
// Plan builder — deterministic DAG from the approved role relationship
// ---------------------------------------------------------------------------

export interface PlanBuildInput {
  role: {
    title: string;
    required_skills: { skill: string; target_proficiency: number }[];
    future_skills: { skill: string; target_proficiency: number }[];
    seniority_level: number;
  };
  verified_skills: { name: string; proficiency: number }[];
  policy_docs: { doc_code: string; title: string }[];
  reopened_skills?: string[]; // skills whose verification failed — learn again
}

const slug = (s: string) => s.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");

function skillProficiency(verified: { name: string; proficiency: number }[], skill: string): number {
  const hit = verified.find((v) => v.name.toLowerCase() === skill.toLowerCase());
  return hit?.proficiency ?? 0;
}

/**
 * Deterministic plan: core provisioning/policy/admin + skill-gap learning tasks
 * + one verification task on the first required-skill gap + survey.
 */
export function buildPlanDefs(input: PlanBuildInput): TaskDef[] {
  const required = (input.role.required_skills ?? []).slice(0, 3);
  const future = (input.role.future_skills ?? []).slice(0, 2);
  const reopened = new Set((input.reopened_skills ?? []).map((s) => s.toLowerCase()));

  const gaps = required.filter(
    (s) => reopened.has(s.skill.toLowerCase()) || skillProficiency(input.verified_skills, s.skill) < s.target_proficiency
  );
  const futureGaps = future.filter((s) => skillProficiency(input.verified_skills, s.skill) < s.target_proficiency);

  const secPolicy = input.policy_docs.find((p) => p.doc_code === "POL-SEC");
  const defs: TaskDef[] = [
    {
      task_code: "it_provisioning",
      title: "IT & Laptop Provisioning",
      task_type: "provisioning",
      owner_role: "it_security",
      required: true,
      non_waivable: true,
      depends_on: [],
      duration_days: 1,
      why_evidence: {
        reason: "Company-issued equipment is mandatory before any system access is granted.",
        source_evidence: [{ source_type: "policy", fact: secPolicy ? `POL-SEC ${secPolicy.title} — work on company-issued devices only.` : "Equipment & Security policy — company-issued devices only." }],
      },
      evidence_requirements: [{ kind: "note", label: "Hardware & asset tag", required: true }],
    },
    {
      task_code: "security_training",
      title: "Security & Compliance Training",
      task_type: "policy",
      owner_role: "employee",
      required: true,
      non_waivable: true,
      depends_on: [],
      duration_days: 1,
      why_evidence: {
        reason: "Annual security training is required for continued system access.",
        source_evidence: [{ source_type: "policy", fact: secPolicy ? `POL-SEC ${secPolicy.title} — annual training required.` : "Equipment & Security policy — annual training required." }],
      },
      evidence_requirements: [{ kind: "note", label: "Training completion reference", required: true }],
    },
    {
      task_code: "payroll",
      title: "Direct Deposit & Payroll Setup",
      task_type: "onboarding_admin",
      owner_role: "hr",
      required: true,
      non_waivable: true,
      depends_on: [],
      duration_days: 0.5,
      why_evidence: {
        reason: "Payroll setup is handled by HR before the first pay run.",
        source_evidence: [{ source_type: "onboarding_admin", fact: "Standard onboarding payroll step." }],
      },
      evidence_requirements: [{ kind: "note", label: "Payroll reference (HR)", required: true }],
    },
    {
      task_code: "access_sso",
      title: "System Access & SSO Enrollment",
      task_type: "access",
      owner_role: "it_security",
      required: true,
      non_waivable: true,
      depends_on: ["it_provisioning", "security_training"],
      duration_days: 0.5,
      why_evidence: {
        reason: "SSO and tool access can only be provisioned after hardware and security training are complete.",
        source_evidence: [{ source_type: "policy", fact: "POL-SEC — MFA mandatory on all accounts; access requires completed security training." }],
      },
      evidence_requirements: [{ kind: "note", label: "MFA / SSO enrollment reference", required: true }],
    },
    {
      task_code: "team_intro",
      title: "Team Introduction & Codebase Walkthrough",
      task_type: "onboarding_admin",
      owner_role: "manager",
      required: true,
      non_waivable: false,
      depends_on: ["access_sso"],
      duration_days: 1,
      why_evidence: {
        reason: "Manager-led introduction and codebase walkthrough require system access first.",
        source_evidence: [{ source_type: "manager", fact: "Standard team integration step after access." }],
      },
      evidence_requirements: [{ kind: "note", label: "Walkthrough held (manager)", required: true }],
    },
  ];

  const firstGap = gaps[0];
  for (const s of gaps) {
    const isReopened = reopened.has(s.skill.toLowerCase());
    const code = isReopened ? `learn_${slug(s.skill)}_reopen` : `learn_${slug(s.skill)}`;
    defs.push({
      task_code: code,
      title: isReopened ? `Re-learning: ${s.skill} (verified gap re-opened)` : `First contribution using ${s.skill}`,
      task_type: "learning",
      owner_role: "employee",
      required: true,
      non_waivable: false,
      depends_on: ["team_intro"],
      duration_days: 1,
      why_evidence: {
        reason: isReopened
          ? `A prior verification attempt did not confirm ${s.skill} at target ${s.target_proficiency}; the gap is re-opened for learning.`
          : `Role requires ${s.skill} at ${s.target_proficiency}; current verified proficiency is ${skillProficiency(input.verified_skills, s.skill)}.`,
        source_evidence: [
          { source_type: "role_fit", fact: `Gap on ${s.skill} vs approved role ${input.role.title} (target ${s.target_proficiency}).` },
          ...(isReopened ? [{ source_type: "verification", fact: `Previous verification of ${s.skill} failed — reason preserved on the superseded task.` }] : []),
        ],
      },
      evidence_requirements: [{ kind: "note", label: `Contribution evidence: ${s.skill}`, required: true }],
    });
    // Verification task on the FIRST gap only.
    if (firstGap && s.skill.toLowerCase() === firstGap.skill.toLowerCase()) {
      defs.push({
        task_code: `verify_${slug(s.skill)}`,
        title: `Verification: ${s.skill} mastery assessment`,
        task_type: "verification",
        owner_role: "employee",
        required: true,
        non_waivable: false,
        depends_on: [code],
        duration_days: 0.5,
        why_evidence: {
          reason: `New assessment evidence replaces further learning for ${s.skill}: verify mastery at target ${s.target_proficiency}.`,
          source_evidence: [{ source_type: "assessment", fact: `Assessment evidence supersedes the learning-only path for ${s.skill}.` }],
        },
        evidence_requirements: [{ kind: "assessment_id", label: "Assessment evidence id", required: true }],
      });
    }
  }
  for (const s of futureGaps) {
    const anchor = gaps[0] ? `learn_${slug(gaps[0].skill)}` : "team_intro";
    defs.push({
      task_code: `future_${slug(s.skill)}`,
      title: `Upskilling plan: ${s.skill}`,
      task_type: "learning",
      owner_role: "employee",
      required: true,
      non_waivable: false,
      depends_on: [anchor],
      duration_days: 1,
      why_evidence: {
        reason: `Future skill ${s.skill} is part of the role's growth path; current verified proficiency ${skillProficiency(input.verified_skills, s.skill)} is below target ${s.target_proficiency}.`,
        source_evidence: [{ source_type: "role_fit", fact: `Future-fit gap on ${s.skill} vs approved role ${input.role.title}.` }],
      },
      evidence_requirements: [{ kind: "note", label: `Upskilling evidence: ${s.skill}`, required: true }],
    });
  }
  defs.push({
    task_code: "survey",
    title: "Onboarding Feedback Survey",
    task_type: "onboarding_admin",
    owner_role: "employee",
    required: true,
    non_waivable: false,
    depends_on: [gaps.length > 0 ? `learn_${slug(gaps[0].skill)}` : "team_intro"],
    duration_days: 0.5,
    why_evidence: {
      reason: "Feedback survey closes the loop after the core journey is underway.",
      source_evidence: [{ source_type: "onboarding_admin", fact: "Standard closing step." }],
    },
    evidence_requirements: [{ kind: "note", label: "Survey submitted", required: true }],
  });
  return defs;
}

// ---------------------------------------------------------------------------
// Carryover on regeneration: preserve valid completed work with a mapping
// ---------------------------------------------------------------------------

export function buildCarryover(prevTasks: PlanTask[], newDefs: TaskDef[], fromPlanId: string, fromVersion: number): { tasks: PlanTask[]; entries: CarryoverEntry[] } {
  const byCode = new Map(prevTasks.map((t) => [t.task_code, t]));
  const entries: CarryoverEntry[] = [];
  const tasks: PlanTask[] = newDefs.map((d) => {
    const prev = byCode.get(d.task_code);
    const fresh: PlanTask = { ...d, state: "pending", start_date: null, due_date: null, topological_level: 0, blocked_reasons: [], blockers: [], waiver: null, completion_record: null, adaptation: null };
    if (!prev) return fresh;
    const defSame =
      prev.title === d.title &&
      prev.task_type === d.task_type &&
      prev.owner_role === d.owner_role &&
      prev.required === d.required &&
      prev.non_waivable === d.non_waivable &&
      prev.duration_days === d.duration_days &&
      JSON.stringify([...prev.depends_on].sort()) === JSON.stringify([...d.depends_on].sort());
    if (!defSame) return fresh;
    if (prev.state === "done" && prev.completion_record) {
      entries.push({ task_code: d.task_code, from_version: fromVersion, from_plan_id: fromPlanId, note: "Completed work preserved on regeneration." });
      return { ...d, state: "done", start_date: prev.start_date, due_date: prev.due_date, topological_level: 0, blocked_reasons: [], blockers: [], waiver: prev.waiver, completion_record: prev.completion_record, adaptation: prev.adaptation };
    }
    if (prev.state === "waived" && prev.waiver) {
      entries.push({ task_code: d.task_code, from_version: fromVersion, from_plan_id: fromPlanId, note: "Waiver preserved on regeneration." });
      return { ...d, state: "waived", start_date: prev.start_date, due_date: prev.due_date, topological_level: 0, blocked_reasons: [], blockers: [], waiver: prev.waiver, completion_record: null, adaptation: prev.adaptation };
    }
    return fresh;
  });
  return { tasks, entries };
}


// ---------------------------------------------------------------------------
// Workforce Review Index engine — deterministic, zero LLM.
// An interpretable, decision-support composite (0-100) that flags WHEN a
// manager/HR review conversation is warranted. It is a REVIEW INDEX, never a
// probability of leaving, and never a performance verdict on its own.
//
// Documented design (Phase 9 baseline, Phase 7 hardened):
// - Factor weights sum to EXACTLY 1.0 (max index = 100).
// - Missing observations are gaps that reduce data completeness; they never
//   count as poor performance and never push anyone into the top tier.
// - A zero attendance baseline does NOT produce an extreme ratio: an absence
//   pattern appearing where none was recorded scores a fixed moderate step.
// - Seeking growth / development interest is reported SEPARATELY and never
//   contributes to the index (growth interest != intent to leave).
// - Priority tiers: low < 40, medium 40-59, high 60-74, review >= 75 (the
//   top tier additionally requires >= REVIEW_MIN_COMPLETENESS data).
// - Phase 7: observed factors, coverage, freshness and review confidence are
//   reported SEPARATELY. Data-quality problems surface BEFORE classification
//   (flags + severity + confidence), insufficient history is distinguished
//   from stable behavior (history_state), and every trend carries explicit
//   favorable/unfavorable semantics. No validated predictive model exists:
//   REVIEW_MODEL_STATUS documents what a future attrition model would require.
// ---------------------------------------------------------------------------

export interface ReviewObservation {
  metric: string; // attendance | engagement | delivery | availability
  period: string; // YYYY-MM
  value: number | null;
  missing: boolean;
}

export interface ReviewIndexInput {
  twin_id?: string;
  promotion_lag_months: number; // months in current band without promotion
  promotion_threshold_months?: number; // default 36 (career-review horizon)
  attendance?: { baseline?: number | null; recent?: number | null }; // unapproved absences/month snapshot
  delivery?: { missed?: number | null; total?: number | null }; // missed milestones / window total
  observations?: ReviewObservation[]; // period-scoped, explicit missing flag
  seeks_growth?: boolean; // self-reported development interest — NEVER adds risk
  engagement_window_months?: number; // default 6
  computed_at?: string; // ISO timestamp for freshness computations
}

export interface ReviewFactor {
  score: number; // 0-1
  weight: number; // factor weight (weights sum to 1.0)
  definition: string; // plain-language factor definition
  source_period: string | null; // evidence period used (or null when n/a)
  note: string | null; // caveat / data-state note
  /** Phase 7: coverage of the evidence this factor relies on (0-1). */
  coverage: number;
  /** Phase 7: how fresh the factor's evidence is (latest period used, or null). */
  freshness: string | null;
}

export interface ReviewTrend {
  metric: string;
  direction: "up" | "down" | "flat" | "insufficient";
  delta: number | null; // (last-first)/first on present values
  first: number | null;
  last: number | null;
  periods: string[];
  /** Phase 7: canonical direction that counts as favorable for this metric. */
  favorable_direction: "up" | "down";
  /** Phase 7: whether the observed change is favorable for the metric. */
  favorable: boolean;
}

/** Phase 7: review confidence — how much the index can be trusted given the
 *  data, NOT a probability of leaving and NOT model calibration. */
export type ReviewConfidence = "high" | "medium" | "low";

export interface DataQualityIssue {
  kind: string; // missing_periods | stale_observations | zero_history | snapshot_only
  detail: string;
}

export interface ReviewIndexResult {
  index: number; // 0-100, weights sum to 1.0
  factors: Record<"career" | "attendance" | "delivery" | "engagement", ReviewFactor>;
  trend: ReviewTrend[];
  data_completeness: number; // 0-1 fraction of expected observation slots present
  missing_data: { metric: string; periods: string[] }[];
  seeking_growth: boolean; // reported separately; NOT part of the index
  priority: "low" | "medium" | "high" | "review";
  priority_gate: { tier_capped: boolean; reason: string | null };
  recommended_fact_finding: string[];
  sensitivity: { individual_absence: boolean; individual_engagement: boolean };
  limitations: string[];
  // Phase 7 additions:
  confidence: ReviewConfidence;
  confidence_reason: string;
  history_state: "none" | "partial" | "adequate";
  data_quality: { issues: DataQualityIssue[]; severity: "ok" | "warning" | "critical" };
  freshness: {
    oldest_observation_period: string | null;
    latest_observation_period: string | null;
    months_since_latest: number | null;
    stale: boolean;
    computed_at: string;
  };
  case_rationale: { factor: string; why: string }[];
}

/** Canonical review bands — the single source of truth the UI and backend both
 *  use so "review bands match across UI and backend". */
export const REVIEW_BANDS: Record<"low" | "medium" | "high" | "review", { min: number; max: number }> = {
  low: { min: 0, max: 39 },
  medium: { min: 40, max: 59 },
  high: { min: 60, max: 74 },
  review: { min: 75, max: 100 },
};

export const REVIEW_BAND_LABELS: Record<keyof typeof REVIEW_BANDS, string> = {
  low: "Low (0-39)",
  medium: "Medium (40-59)",
  high: "High (60-74)",
  review: "Review (75-100)",
};

/** Map an index value to its canonical band (backend + UI agree on this). */
export function reviewBandFor(index: number): "low" | "medium" | "high" | "review" {
  if (index >= REVIEW_BANDS.review.min) return "review";
  if (index >= REVIEW_BANDS.high.min) return "high";
  if (index >= REVIEW_BANDS.medium.min) return "medium";
  return "low";
}

/** Phase 7: per-metric semantics so trends are rendered with the CORRECT
 *  favorable/unfavorable meaning (attendance up = bad; delivery/engagement
 *  up = good). */
export const REVIEW_METRIC_FAVORABLE_DIRECTION: Record<string, "up" | "down"> = {
  attendance: "down",
  delivery: "up",
  engagement: "up",
};

export type ReviewBand = "low" | "medium" | "high" | "review";

/** Phase 7: fewer distinct present periods than this = "insufficient history"
 *  (distinct from stable behavior, which requires enough data to actually be flat). */
export const REVIEW_HISTORY_MIN_PERIODS = 3;
/** Phase 7: latest observation older than this many months = stale. */
export const STALE_OBSERVATION_MONTHS = 6;

/** Phase 7 — honest model status. No validated attrition/predictive model
 *  exists; this is the (unchanged) honest REVIEW INDEX terminology the spec
 *  asks to preserve. The future-ML checklist (spec items 21-26) is documented
 *  here so nobody mistakes the heuristic composite for a calibrated predictor. */
export const REVIEW_MODEL_STATUS = {
  has_validated_predictive_model: false,
  label: "Workforce Review Index — a documented heuristic composite (0-100), not a probability of leaving and not a calibrated prediction.",
  future_ml_requirements: [
    "21. Define an explicit outcome (e.g., voluntary attrition within a horizon) and a prediction horizon.",
    "22. Split by time (train on earlier periods, evaluate on later) and prevent post-outcome leakage.",
    "23. Compare against interpretable baselines (e.g., historical base rate) before any complex model.",
    "24. Report calibration, precision/recall, cohort stability and missingness handling.",
    "25. Clearly distinguish synthetic-data demonstrations from externally validated predictive performance.",
    "26. Keep any future prediction as restricted decision support, never automatic action.",
  ],
  note: "None of the above is implemented because no suitable labeled outcome dataset exists in this deployment. Until it does, every case stays a review index with documented heuristics.",
} as const;

// Weights — sum is exactly 1.0 (0.30 + 0.30 + 0.30 + 0.10).
export const REVIEW_WEIGHTS = { career: 0.3, attendance: 0.3, delivery: 0.3, engagement: 0.1 } as const;
export const CAREER_REVIEW_THRESHOLD_MONTHS = 36;
export const ATTENDANCE_CAP_RATIO = 2; // doubling the baseline absence rate = full factor
export const ZERO_BASELINE_STEP = 0.5; // fixed moderate step (NOT 1.0) when a pattern appears from zero
export const REVIEW_MIN_COMPLETENESS = 0.75; // top tier requires at least this much data
export const TREND_HALF_PERIODS = 3; // compare means of first/last N present periods

function clamp01(v: number): number {
  return Math.min(1, Math.max(0, v));
}

function presentValues(obs: ReviewObservation[], metric: string): { period: string; value: number }[] {
  return (obs ?? [])
    .filter((o) => o.metric === metric && !o.missing && typeof o.value === "number")
    .sort((a, b) => a.period.localeCompare(b.period))
    .map((o) => ({ period: o.period, value: o.value as number }));
}

export function computeReviewIndex(input: ReviewIndexInput): ReviewIndexResult {
  const threshold = input.promotion_threshold_months ?? CAREER_REVIEW_THRESHOLD_MONTHS;
  const engWindow = input.engagement_window_months ?? 6;
  const obs = input.observations ?? [];
  const seeksGrowth = input.seeks_growth === true;
  const computedAt = input.computed_at ?? new Date().toISOString();

  // --- F_career: time in band beyond the career-review horizon --------------
  const lag = Math.max(0, Number(input.promotion_lag_months) || 0);
  const career = clamp01(lag / threshold);
  const careerFactor: ReviewFactor = {
    score: career,
    weight: REVIEW_WEIGHTS.career,
    definition: `Months in current band without a promotion, scaled against the ${threshold}-month career-review horizon.`,
    source_period: "twin profile (as of computed_at)",
    coverage: 1,
    freshness: "profile snapshot",
    note: career >= 0.5 ? "Extended time in band warrants a career-path conversation — not, by itself, a risk conclusion." : null,
  };

  // --- F_attendance: deviation of recent absence rate from OWN baseline ------
  const base = input.attendance?.baseline;
  const recent = input.attendance?.recent;
  let attendanceScore = 0;
  let attendanceNote: string | null = null;
  const attendanceCoverage = base === null || base === undefined || recent === null || recent === undefined ? 0 : 1;
  if (attendanceCoverage === 0) {
    attendanceNote = "No absence snapshot recorded — treated as unknown, not penalized.";
  } else if (Number(base) > 0) {
    const b = Math.max(0, Number(base));
    const r = Math.max(0, Number(recent));
    if (r > b) {
      attendanceScore = clamp01((r / b - 1) / (ATTENDANCE_CAP_RATIO - 1));
      if (attendanceScore >= 0.5) attendanceNote = "Recent absence rate is materially above this person's own baseline — verify with the manager.";
    }
  } else {
    // Zero baseline: fixed moderate step, never an extreme ratio from 0.
    attendanceScore = Math.max(0, Number(recent)) > 0 ? ZERO_BASELINE_STEP : 0;
    if (attendanceScore > 0) {
      attendanceNote = `No unapproved absence was recorded before; a pattern appeared (scored a fixed ${ZERO_BASELINE_STEP} step to avoid an extreme ratio from a zero baseline).`;
    }
  }
  const attendanceFactor: ReviewFactor = {
    score: attendanceScore,
    weight: REVIEW_WEIGHTS.attendance,
    definition: "Deviation of the recent unapproved-absence rate from the person's own baseline (pattern change, never cross-person counts).",
    source_period: "most recent absence snapshot (HRIS)",
    coverage: attendanceCoverage,
    freshness: "HRIS snapshot",
    note: attendanceNote,
  };

  // --- F_delivery: missed milestones / window total --------------------------
  const total = Math.max(0, Number(input.delivery?.total) || 0);
  const missed = Math.max(0, Math.min(total, Number(input.delivery?.missed) || 0));
  const deliveryScore = total > 0 ? missed / total : 0;
  const deliveryFactor: ReviewFactor = {
    score: deliveryScore,
    weight: REVIEW_WEIGHTS.delivery,
    definition: "Missed milestones as a share of the review window's total — a workload/availability indicator, not a quality verdict.",
    source_period: "recent delivery window (missed/total)",
    coverage: total > 0 ? 1 : 0,
    freshness: "delivery window snapshot",
    note: total <= 0 ? "No delivery observations in window — treated as unknown, not penalized." : deliveryScore >= 0.5 ? "High miss share — investigate workload/resourcing before drawing conclusions." : null,
  };

  // --- F_engagement: trend over the observation window (explicit gaps) -------
  const eng = presentValues(obs, "engagement").slice(-engWindow);
  let engagementScore = 0;
  let engNote: string | null = null;
  if (eng.length < 2) {
    engNote = eng.length === 0 ? "No engagement observations — treated as unknown, not penalized." : "Too few engagement observations to score.";
  } else {
    const half = Math.max(1, Math.floor(eng.length / 2));
    const first = eng.slice(0, half).reduce((s, p) => s + p.value, 0) / half;
    const second = eng.slice(eng.length - half).reduce((s, p) => s + p.value, 0) / half;
    if (first > 0) {
      engagementScore = clamp01((first - second) / first); // decline in engagement raises the factor
      if (engagementScore > 0) engNote = "Engagement observations trend downward across the window.";
    }
  }
  const engagementFactor: ReviewFactor = {
    score: engagementScore,
    weight: REVIEW_WEIGHTS.engagement,
    definition: `Decline in engagement observations over the last ${engWindow} months (first-vs-second-half means). Missing periods are gaps, not poor performance.`,
    source_period: eng.length >= 2 ? `${eng[0].period} → ${eng[eng.length - 1].period}` : null,
    coverage: eng.length >= 2 ? 1 : eng.length === 1 ? 0.5 : 0,
    freshness: eng.length >= 2 ? eng[eng.length - 1].period : null,
    note: engNote,
  };

  // --- Composite index --------------------------------------------------------
  const index = Math.round(
    100 *
      (REVIEW_WEIGHTS.career * career +
        REVIEW_WEIGHTS.attendance * attendanceScore +
        REVIEW_WEIGHTS.delivery * deliveryScore +
        REVIEW_WEIGHTS.engagement * engagementScore)
  );

  // --- Data completeness + missing data --------------------------------------
  const metricsSeen = new Set((obs ?? []).map((o) => o.metric));
  const periodSet = new Set((obs ?? []).map((o) => o.period));
  const expected = metricsSeen.size * periodSet.size;
  const present = (obs ?? []).filter((o) => !o.missing && typeof o.value === "number").length;
  const data_completeness = expected > 0 ? present / expected : 0;

  const missingByMetric = new Map<string, string[]>();
  for (const o of obs ?? []) {
    if (o.missing || o.value === null || o.value === undefined) {
      missingByMetric.set(o.metric, [...(missingByMetric.get(o.metric) ?? []), o.period]);
    }
  }
  const missing_data = [...missingByMetric.entries()]
    .map(([metric, periods]) => ({ metric, periods: periods.sort() }))
    .sort((a, b) => a.metric.localeCompare(b.metric));

  // --- Freshness (Phase 7) ----------------------------------------------------
  const allPresent = (obs ?? [])
    .filter((o) => !o.missing && typeof o.value === "number")
    .map((o) => o.period)
    .sort();
  const oldest = allPresent[0] ?? null;
  const latest = allPresent[allPresent.length - 1] ?? null;
  let monthsSinceLatest: number | null = null;
  if (latest) {
    const [ly, lm] = latest.split("-").map(Number);
    const now = new Date(computedAt);
    monthsSinceLatest = (now.getUTCFullYear() - ly) * 12 + (now.getUTCMonth() + 1 - lm);
  }
  const stale = monthsSinceLatest !== null && monthsSinceLatest > STALE_OBSERVATION_MONTHS;

  // --- History state (Phase 7): insufficient history vs stable behavior ------
  const distinctPresentPeriods = new Set(allPresent).size;
  const history_state: ReviewIndexResult["history_state"] =
    distinctPresentPeriods === 0 ? "none" : distinctPresentPeriods < REVIEW_HISTORY_MIN_PERIODS ? "partial" : "adequate";

  // --- Data quality surfaced BEFORE classification (Phase 7) ------------------
  const issues: DataQualityIssue[] = [];
  if (distinctPresentPeriods === 0) {
    issues.push({ kind: "zero_history", detail: "No longitudinal observations exist — the index reflects profile snapshots only (career lag, absence and delivery snapshots)." });
  } else if (distinctPresentPeriods < REVIEW_HISTORY_MIN_PERIODS) {
    issues.push({ kind: "snapshot_only", detail: `Only ${distinctPresentPeriods} observation period(s) present — trends cannot be established yet.` });
  }
  if (missing_data.length > 0) {
    const missingCount = missing_data.reduce((n, m) => n + m.periods.length, 0);
    issues.push({ kind: "missing_periods", detail: `${missingCount} observation slot(s) missing across ${missing_data.length} metric(s).` });
  }
  if (stale) {
    issues.push({ kind: "stale_observations", detail: `Latest observation is ${monthsSinceLatest} months old (stale threshold: ${STALE_OBSERVATION_MONTHS}).` });
  }
  const severity: ReviewIndexResult["data_quality"]["severity"] =
    distinctPresentPeriods === 0 || data_completeness < 0.4 ? "critical" : data_completeness < REVIEW_MIN_COMPLETENESS || stale ? "warning" : "ok";

  // --- Review confidence (Phase 7): data-driven, explicitly not a probability --
  let confidence: ReviewConfidence;
  let confidence_reason: string;
  if (distinctPresentPeriods === 0 || data_completeness < 0.5 || stale) {
    confidence = "low";
    confidence_reason = `Low — longitudinal observation history is ${distinctPresentPeriods === 0 ? "absent" : "incomplete"} (${Math.round(data_completeness * 100)}% complete${stale ? ", stale" : ""}). Use the index as a starting point, not a signal.`;
  } else if (data_completeness < REVIEW_MIN_COMPLETENESS || distinctPresentPeriods < 6) {
    confidence = "medium";
    confidence_reason = `Medium — coverage is ${Math.round(data_completeness * 100)}% across ${distinctPresentPeriods} period(s); confirm with a conversation before any conclusion.`;
  } else {
    confidence = "high";
    confidence_reason = `High — coverage is ${Math.round(data_completeness * 100)}% across ${distinctPresentPeriods} period(s) and observations are fresh.`;
  }

  // --- Trend per metric (favorable/unfavorable semantics) ---------------------
  const trend: ReviewTrend[] = ["attendance", "engagement", "delivery"].map((metric) => {
    const vals = presentValues(obs, metric);
    const favorable_direction = REVIEW_METRIC_FAVORABLE_DIRECTION[metric] ?? "up";
    if (vals.length < 2 * TREND_HALF_PERIODS) {
      return { metric, direction: "insufficient", delta: null, first: null, last: null, periods: vals.map((v) => v.period), favorable_direction, favorable: false };
    }
    const firstMean = vals.slice(0, TREND_HALF_PERIODS).reduce((s, p) => s + p.value, 0) / TREND_HALF_PERIODS;
    const lastMean = vals.slice(-TREND_HALF_PERIODS).reduce((s, p) => s + p.value, 0) / TREND_HALF_PERIODS;
    const delta = firstMean > 0 ? (lastMean - firstMean) / firstMean : null;
    const eps = 0.03;
    const direction = delta === null || Math.abs(delta) < eps ? "flat" : delta > 0 ? "up" : "down";
    const favorable = direction === favorable_direction;
    return { metric, direction, delta, first: +firstMean.toFixed(3), last: +lastMean.toFixed(3), periods: vals.map((v) => v.period), favorable_direction, favorable };
  });

  // --- Priority tier (review index, not probability) -------------------------
  let priority: ReviewIndexResult["priority"] = "low";
  if (index >= 75) priority = "review";
  else if (index >= 60) priority = "high";
  else if (index >= 40) priority = "medium";

  let tierCapped = false;
  let gateReason: string | null = null;
  if (priority === "review" && history_state === "none") {
    priority = "high";
    tierCapped = true;
    gateReason = "The index qualifies for the top tier on profile snapshots alone, but there is zero longitudinal observation history — the case is honestly capped until history exists. It is not an alarming classification on no data.";
  } else if (priority === "review" && data_completeness < REVIEW_MIN_COMPLETENESS) {
    priority = "high";
    tierCapped = true;
    gateReason = `Index qualifies for the top tier, but observation data completeness is ${Math.round(data_completeness * 100)}% (min ${Math.round(REVIEW_MIN_COMPLETENESS * 100)}% required) — missing data never escalates a case; complete the gaps before treating this as a top-priority review.`;
  }

  // --- Recommended fact-finding (deterministic, action-oriented) -------------
  const recommended_fact_finding: string[] = [];
  const case_rationale: { factor: string; why: string }[] = [];
  if (attendanceScore >= 0.5) {
    recommended_fact_finding.push("Verify the unapproved-absence pattern with the employee's manager before any conclusion.");
    case_rationale.push({ factor: "attendance", why: attendanceNote ?? "The recent absence rate is materially above the person's own baseline." });
  }
  const engTrendDir = trend.find((t) => t.metric === "engagement")?.direction ?? "insufficient";
  if (engagementScore >= 0.5 || engTrendDir === "down" || engTrendDir === "insufficient") {
    recommended_fact_finding.push("Collect an engagement pulse and discuss drivers in a 1:1 — do not infer reasons from the numbers.");
    if (engTrendDir === "down") case_rationale.push({ factor: "engagement", why: "Engagement observations trend downward across the window." });
    else if (engTrendDir === "insufficient") case_rationale.push({ factor: "engagement", why: "Engagement history is insufficient to judge direction — a conversation is the only honest next step." });
  }
  if (career >= 0.5) {
    recommended_fact_finding.push("Open a career-path conversation; review band-change timing and growth options.");
    case_rationale.push({ factor: "career", why: `${Math.round(lag)} months in band without a promotion — beyond the ${threshold}-month career-review horizon.` });
  }
  if (deliveryScore >= 0.5) {
    recommended_fact_finding.push("Review workload and resourcing; distinguish missed deadlines caused by capacity from quality issues.");
    case_rationale.push({ factor: "delivery", why: `${Math.round(missed)} of ${Math.round(total)} milestones missed in the delivery window.` });
  }
  if (data_completeness < REVIEW_MIN_COMPLETENESS) {
    recommended_fact_finding.push(`Observation history is ${Math.round(data_completeness * 100)}% complete — collect the missing periods before finalizing the review.`);
  }
  if (seeksGrowth) {
    recommended_fact_finding.push("Reported development interest is a growth conversation, not a risk signal — plan scope/mentoring, do not flag for retention.");
  }

  return {
    index,
    factors: { career: careerFactor, attendance: attendanceFactor, delivery: deliveryFactor, engagement: engagementFactor },
    trend,
    data_completeness: +data_completeness.toFixed(3),
    missing_data,
    seeking_growth: seeksGrowth,
    priority,
    priority_gate: { tier_capped: tierCapped, reason: gateReason },
    recommended_fact_finding,
    sensitivity: { individual_absence: attendanceScore > 0, individual_engagement: eng.length >= 2 },
    limitations: [
      "Workforce Review Index is an interpretable decision-support composite (0-100), NOT a probability of leaving.",
      "Factor weights and definitions are fixed, documented heuristics; validate local assumptions before operational use.",
      "Missing observations are treated as data gaps (lower completeness), never as poor performance.",
      "Seeking-growth / development interest is reported separately and never contributes to the index.",
      "The attendance factor uses the most recent absence snapshot; confirm with the manager before conclusions.",
      "Review confidence reflects data coverage and freshness — it is not a calibrated model reliability measure.",
    ],
    confidence,
    confidence_reason,
    history_state,
    data_quality: { issues, severity },
    freshness: {
      oldest_observation_period: oldest,
      latest_observation_period: latest,
      months_since_latest: monthsSinceLatest,
      stale,
      computed_at: computedAt,
    },
    case_rationale,
  };
}

// Stable version hash over the index-relevant source rows. Used to detect when
// cached review artifacts must be invalidated because the underlying data changed.
export function reviewSourceHash(input: ReviewIndexInput): string {
  const payload = {
    lag: input.promotion_lag_months,
    threshold: input.promotion_threshold_months ?? CAREER_REVIEW_THRESHOLD_MONTHS,
    attendance: input.attendance ?? {},
    delivery: input.delivery ?? {},
    seeks_growth: input.seeks_growth === true,
    observations: (input.observations ?? [])
      .map((o) => `${o.metric}|${o.period}|${String(o.value)}|${o.missing ? 1 : 0}`)
      .sort(),
  };
  return fnv1aHex(JSON.stringify(payload));
}

// FNV-1a 32-bit, hex — deterministic across platforms.
// Named fnv1aHex (not fnv1a) so the flat function bundle never collides with
// other shared modules that keep a private fnv1a.
export function fnv1aHex(str: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}


// ---------------------------------------------------------------------------
// WorkSense Skill Intelligence Graph engine — the shared, deterministic core.
// Zero LLM calls. Imported by backend functions (Recruitment, Onboarding,
// Recommendation Hub) — never recomputed per page view; results are persisted
// into digital_twins.computed_fits[] and, for skill-match, the durable
// skill_fits table.
//
// Phase 8: every fit is versioned against the engine, the person's evidence
// and the requisition content; cached results are marked stale when any of
// them change. Adjacency and transferable support carry explicit limitations
// (never direct equivalence). The evidence section counts DISTINCT artifacts,
// not skill assertions.
// ---------------------------------------------------------------------------

export type VerificationRigor = "low" | "medium" | "high";

/** Bump when the scoring semantics change — stale cached fits are recomputed. */
export const ENGINE_VERSION = "2";

export interface SkillClaim {
  name: string;
  proficiency: number;
  evidence_source: string;
  verification_rigor: VerificationRigor;
}

export type EdgeType = "PREREQUISITE_OF" | "ADJACENT_TO" | "TRANSFERABLE_TO";

export interface GraphEdge {
  target_skill: string;
  type: EdgeType;
  weight: number; // 0.0 - 1.0
}

export interface GraphSkill {
  skill: string;
  category: string;
  outgoing_edges: GraphEdge[];
}

export interface RequiredSkill {
  skill: string;
  target_proficiency: number;
}

export type Classification = "direct" | "adjacent" | "transferable" | "gap";

export interface FitItem {
  skill: string;
  classification: Classification;
  required_proficiency: number;
  candidate_proficiency: number | null;
  edge: { from_skill: string; type: EdgeType; weight: number } | null;
  contribution: number | null;
  reason: string;
  /** Phase 8: honest limitation of this classification (never equivalence).
   *  Optional so legacy generated fits remain valid. */
  limitation?: string | null;
}

export interface FitRecord {
  target_type: "requisition";
  target_id: string;
  target_title: string;
  scenario: "current" | "future";
  score: number;
  sections: {
    direct: { value: number; items: FitItem[] };
    adjacent: { value: number; items: FitItem[] };
    evidence: { value: number; artifact_count: number; threshold: number };
    seniority: { value: number; candidate_level: number; role_level: number };
  };
  classification: {
    direct: FitItem[];
    adjacent: FitItem[];
    transferable: FitItem[];
    gaps: FitItem[];
  };
  /** Phase 8 / Batch E: what the fit is versioned against (stale detection).
   *  Optional so legacy generated fits remain valid; missing versions are
   *  treated as stale. graph + context were added in Batch E — fits computed
   *  before them are recomputed once. */
  versions?: {
    engine: string;
    evidence: string;
    requisition: string;
    graph?: string;
    context?: string;
  };
  /** Phase 8: named horizon + assumption the fit was computed under. */
  assumptions?: {
    horizon: string;
    note: string;
  };
  computed_at: string;
}

// Validated weights — do not change.
export const MATCH_WEIGHTS = {
  direct: 0.5,
  adjacent: 0.25,
  evidence: 0.15,
  seniority: 0.1,
} as const;

export const DEFAULT_EVIDENCE_THRESHOLD = 5;

const norm = (s: string) => s.trim().toLowerCase();

export function findEdge(
  skillGraph: GraphSkill[],
  from: string,
  to: string,
  type: EdgeType
): GraphEdge | null {
  const node = skillGraph.find((n) => norm(n.skill) === norm(from));
  const edge = node?.outgoing_edges.find(
    (e) => norm(e.target_skill) === norm(to) && e.type === type
  );
  return edge ?? null;
}

const round3 = (n: number) => Math.round(n * 1000) / 1000;

/** Deterministic FNV-1a hex (uniquely named to avoid bundle collisions). */
export function graphFnv1aHex(str: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

/** Version hash over the requisition's skill content (phase 8 stale check). */
export function requisitionContentHash(
  requiredSkills: RequiredSkill[],
  futureSkills: RequiredSkill[],
  seniorityLevel: number
): string {
  const payload = [
    ...(requiredSkills ?? []).map((s) => `${s.skill}|${s.target_proficiency}`).sort(),
    ...(futureSkills ?? []).map((s) => `future:${s.skill}|${s.target_proficiency}`).sort(),
    `level:${seniorityLevel}`,
  ].join(";");
  return graphFnv1aHex(payload);
}

/** Version hash over the person's resolved skill claims (evidence version). */
export function claimHash(claims: SkillClaim[]): string {
  const payload = (claims ?? [])
    .map((c) => `${c.name}|${c.proficiency}|${c.evidence_source}|${c.verification_rigor}`)
    .sort()
    .join(";");
  return graphFnv1aHex(payload);
}

/** Batch E (E3): version hash over the whole graph (nodes + typed edges), so a
 *  taxonomy change invalidates fits that relied on those edges. */
export function graphContentHash(
  graph: { skill: string; outgoing_edges: { target_skill: string; type: string; weight: number }[] }[]
): string {
  const payload = (graph ?? [])
    .flatMap((n) => [
      `node:${n.skill}`,
      ...(n.outgoing_edges ?? []).map((e) => `${n.skill}|${e.type}|${e.target_skill}|${e.weight}`),
    ])
    .sort()
    .join(";");
  return graphFnv1aHex(payload);
}

/** Batch E (E3): person-level context that changes the score but is not part
 *  of the claim set — seniority and the number of independent evidence
 *  artifacts behind the claims. */
export function personContextHash(candidateLevel: number, evidenceArtifactCount: number | undefined, claimCount: number): string {
  const artifacts = evidenceArtifactCount !== undefined ? evidenceArtifactCount : claimCount;
  return graphFnv1aHex(`level:${candidateLevel}|artifacts:${artifacts}`);
}

/** Phase 8 / Batch E: a cached fit is stale when the engine, the person's
 *  evidence, the requisition content, the skill graph, or the person-level
 *  context (seniority / evidence artifact count) changed since it was
 *  computed. */
export function fitIsStale(
  fit: FitRecord | null,
  current: { engine: string; evidence: string; requisition: string; graph?: string; context?: string }
): boolean {
  if (!fit) return true;
  const v = fit.versions;
  if (!v) return true; // pre-version fits are always stale
  if (v.engine !== current.engine || v.evidence !== current.evidence || v.requisition !== current.requisition) return true;
  // Batch E: legacy fits lack graph/context fingerprints -> stale once.
  if (current.graph !== undefined && (v.graph ?? undefined) !== current.graph) return true;
  if (current.context !== undefined && (v.context ?? undefined) !== current.context) return true;
  return false;
}

const HORIZON_LABEL: Record<string, string> = {
  current: "Current requirements — as recorded on the requisition today.",
  future: "12–24 month outlook — derived from the requisition's future_skills. Assumption: these skills are the expected demand; edit the requisition to change them.",
};

export function computeFit(params: {
  candidateSkills: SkillClaim[];
  candidateLevel: number;
  requiredSkills: RequiredSkill[];
  roleLevel: number;
  skillGraph: GraphSkill[];
  threshold?: number;
  target: { type: "requisition"; id: string; title: string };
  scenario: "current" | "future";
  computedAt?: string;
  /** Phase 8: distinct artifact count behind the claims (dedup, never
   *  one-per-assertion). Falls back to claim count when not supplied. */
  evidenceArtifactCount?: number;
  /** Phase 8: requisition content hash (stale detection). */
  requisitionVersion?: string;
}): FitRecord {
  const threshold = params.threshold ?? DEFAULT_EVIDENCE_THRESHOLD;
  const graph = params.skillGraph;

  const directItems: FitItem[] = [];
  const adjacentItems: FitItem[] = [];
  const transferableItems: FitItem[] = [];
  const gapItems: FitItem[] = [];
  const directValues: number[] = [];
  const adjacentValues: number[] = [];

  let ownedCount = 0;
  for (const req of params.requiredSkills) {
    const own = params.candidateSkills.find((s) => norm(s.name) === norm(req.skill));
    const ownProficiency = own?.proficiency ?? 0;

    // S_direct: min(1, candidate/required) across ALL required skills — 0 for
    // skills not owned; partial proficiency still contributes its ratio.
    const ratio = own ? Math.min(1, ownProficiency / req.target_proficiency) : 0;
    directValues.push(ratio);

    if (own) {
      ownedCount++;
      if (ownProficiency >= req.target_proficiency) {
        directItems.push({
          skill: req.skill,
          classification: "direct",
          required_proficiency: req.target_proficiency,
          candidate_proficiency: ownProficiency,
          edge: null,
          contribution: ratio,
          reason: `Holds ${req.skill} at ${ownProficiency}/${req.target_proficiency} required.`,
          limitation: null,
        });
      } else {
        directItems.push({
          skill: req.skill,
          classification: "direct",
          required_proficiency: req.target_proficiency,
          candidate_proficiency: ownProficiency,
          edge: null,
          contribution: ratio,
          reason: `Holds ${req.skill} at ${ownProficiency}/${req.target_proficiency} — below the required bar.`,
          limitation: null,
        });
      }
      continue;
    }

    // Adjacent: no direct skill, but a real ADJACENT_TO edge exists (with the
    // candidate's proficiency weighting the edge). Never a direct equivalence.
    let bestAdj: { from: string; edge: GraphEdge; value: number } | null = null;
    for (const claim of params.candidateSkills) {
      const edge = findEdge(graph, claim.name, req.skill, "ADJACENT_TO");
      if (edge) {
        const value = (claim.proficiency / 5) * edge.weight;
        if (!bestAdj || value > bestAdj.value) bestAdj = { from: claim.name, edge, value };
      }
    }
    if (bestAdj) {
      adjacentValues.push(bestAdj.value);
      adjacentItems.push({
        skill: req.skill,
        classification: "adjacent",
        required_proficiency: req.target_proficiency,
        candidate_proficiency: ownProficiency || null,
        edge: { from_skill: bestAdj.from, type: "ADJACENT_TO", weight: bestAdj.edge.weight },
        contribution: bestAdj.value,
        reason: `No direct ${req.skill}; backed by ${bestAdj.from} → ${req.skill} (ADJACENT_TO, ${bestAdj.edge.weight.toFixed(2)}).`,
        limitation: "Adjacent support is NOT direct equivalence: this person has no evidence for the required skill itself. Confirm real capability before relying on it.",
      });
      continue;
    }

    // Transferable: no direct/adjacent edge, but a TRANSFERABLE_TO edge or a
    // strong same-category relationship exists.
    let transfer: { from: string; edge: GraphEdge | null; via: string } | null = null;
    for (const claim of params.candidateSkills) {
      const edge = findEdge(graph, claim.name, req.skill, "TRANSFERABLE_TO");
      if (edge) {
        transfer = { from: claim.name, edge, via: "edge" };
        break;
      }
      if (!transfer) {
        const ownNode = graph.find((n) => norm(n.skill) === norm(claim.name));
        const reqNode = graph.find((n) => norm(n.skill) === norm(req.skill));
        if (ownNode && reqNode && ownNode.category && ownNode.category === reqNode.category) {
          transfer = { from: claim.name, edge: null, via: `same category (${ownNode.category})` };
        }
      }
    }
    if (transfer) {
      transferableItems.push({
        skill: req.skill,
        classification: "transferable",
        required_proficiency: req.target_proficiency,
        candidate_proficiency: ownProficiency || null,
        edge: transfer.edge
          ? { from_skill: transfer.from, type: "TRANSFERABLE_TO", weight: transfer.edge.weight }
          : null,
        contribution: null,
        reason: transfer.edge
          ? `No direct or adjacent path; ${transfer.from} → ${req.skill} is transferable.`
          : `No direct or adjacent path; ${transfer.from} shares the ${transfer.via}.`,
        limitation: "Transferable support is the weakest signal: it does not establish any proficiency in the required skill and contributes no points to the score. Treat it as a development candidate, not capability.",
      });
      continue;
    }

    gapItems.push({
      skill: req.skill,
      classification: "gap",
      required_proficiency: req.target_proficiency,
      candidate_proficiency: ownProficiency || null,
      edge: null,
      contribution: null,
      reason: `No direct, adjacent, or transferable path found for ${req.skill}.`,
      limitation: null,
    });
  }

  const S_direct =
    directValues.length > 0
      ? directValues.reduce((a, b) => a + b, 0) / directValues.length
      : 0;

  const missing = params.requiredSkills.length - ownedCount; // skills not owned at all
  const S_adjacent =
    missing === 0
      ? 1 // nothing missing to be adjacent to
      : adjacentValues.length > 0
        ? adjacentValues.reduce((a, b) => a + b, 0) / missing
        : 0;

  // Phase 8: evidence counts DISTINCT artifacts (deduped by source), never one
  // point per skill assertion. Fallback to the claim count for legacy callers.
  const artifactCount =
    params.evidenceArtifactCount !== undefined
      ? params.evidenceArtifactCount
      : params.candidateSkills.filter((s) => s.verification_rigor === "high" || s.verification_rigor === "medium").length;
  const S_evidence = Math.min(1, artifactCount / threshold);

  const S_seniority = Math.max(0, 1 - 0.2 * Math.abs(params.candidateLevel - params.roleLevel));

  const score =
    MATCH_WEIGHTS.direct * S_direct +
    MATCH_WEIGHTS.adjacent * S_adjacent +
    MATCH_WEIGHTS.evidence * S_evidence +
    MATCH_WEIGHTS.seniority * S_seniority;

  return {
    target_type: params.target.type,
    target_id: params.target.id,
    target_title: params.target.title,
    scenario: params.scenario,
    score: round3(score),
    sections: {
      direct: { value: round3(S_direct), items: directItems },
      adjacent: { value: round3(S_adjacent), items: adjacentItems },
      evidence: { value: round3(S_evidence), artifact_count: artifactCount, threshold },
      seniority: {
        value: round3(S_seniority),
        candidate_level: params.candidateLevel,
        role_level: params.roleLevel,
      },
    },
    classification: {
      direct: directItems,
      adjacent: adjacentItems,
      transferable: transferableItems,
      gaps: gapItems,
    },
    versions: {
      engine: ENGINE_VERSION,
      evidence: claimHash(params.candidateSkills),
      requisition: params.requisitionVersion ?? "unknown",
      graph: graphContentHash(graph),
      context: personContextHash(params.candidateLevel, params.evidenceArtifactCount, params.candidateSkills.length),
    },
    assumptions: {
      horizon: params.scenario === "future" ? "12–24 month outlook" : "Current",
      note: HORIZON_LABEL[params.scenario],
    },
    computed_at: params.computedAt ?? new Date().toISOString(),
  };
}

/** Cache key for computed_fits[] entries. */
export function fitKey(record: { target_type: string; target_id: string; scenario: string }) {
  return `${record.target_type}|${record.target_id}|${record.scenario}`;
}

/**
 * Skill-match authorization — a pure, role-scoped decision shared by the
 * backend function (server enforcement) and unit tests. Deliberately does not
 * decide ownership on the client.
 *
 * Scopes:
 *   org        — administrator (any twin) / HR partner (workforce twins only)
 *   candidates — recruiter (candidate twins only)
 *   team       — manager (direct/recursive reports, self handled separately)
 *   self       — manager self / employee self
 *   denied     — everything else (IT, candidate callers, cross-org, out of scope)
 */
export type SkillMatchScope = "org" | "candidates" | "team" | "self" | "denied";

export interface AuthorizeSkillMatchArgs {
  callerRole: string;
  callerOrgId: string;
  callerTwinId: string;
  targetOrgId: string;
  targetTwinId: string;
  targetRole: string;
  /** Pre-resolved subtree check (manager only); a failed lookup must be false. */
  targetIsInCallerTeam: boolean;
}

export function authorizeSkillMatch(args: AuthorizeSkillMatchArgs): SkillMatchScope {
  const { callerRole, callerOrgId, callerTwinId, targetOrgId, targetTwinId, targetRole, targetIsInCallerTeam } = args;
  if (!callerOrgId || targetOrgId !== callerOrgId) return "denied";

  if (callerRole === "hr_executive") return "org";
  if (callerRole === "hr_partner") return targetRole === "candidate" ? "denied" : "org";
  if (callerRole === "recruiter") return targetRole === "candidate" ? "candidates" : "denied";
  if (callerRole === "manager") {
    if (targetTwinId === callerTwinId) return "self";
    return targetIsInCallerTeam ? "team" : "denied";
  }
  if (callerRole === "employee") {
    return targetTwinId === callerTwinId ? "self" : "denied";
  }
  return "denied";
}


import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";








const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

function jsonResponse(body: unknown, status = 200, extraHeaders: Record<string, string> = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json", ...extraHeaders },
  });
}

async function ensureDemoAuthUsers(supabase) {
  const created: string[] = [];
  const idByEmail: Record<string, string> = {};
  const { data: allUsers, error: listErr } = await supabase.auth.admin.listUsers({ page: 1, perPage: 1000 });
  if (listErr) throw new Error(`Failed to list auth users: ${listErr.message}`);
  const usersByEmail = new Map<string, string>();
  for (const ru of (allUsers?.users ?? []) as { email?: string; id?: string }[]) {
    if (ru.email && ru.id) usersByEmail.set(ru.email, ru.id);
  }

  for (const account of DEMO_ACCOUNTS) {
    const existingId = usersByEmail.get(account.email);
    if (existingId) {
      idByEmail[account.email] = existingId;
      continue;
    }
    const { data, error } = await supabase.auth.admin.createUser({
      email: account.email,
      password: account.password,
      email_confirm: true,
      user_metadata: { name: account.name, is_demo: true },
    });
    if (error) throw new Error(`Failed to create demo user ${account.email}: ${error.message}`);
    created.push(account.email);
    idByEmail[account.email] = data.user.id;
  }
  return { created, idByEmail };
}

const rigorFor = (state: string) =>
  state === "reviewer_confirmed" ? "high" : state === "assessment_supported" ? "medium" : "low";
const sourceFor = (state: string) =>
  state === "reviewer_confirmed" ? "evidence_review" : state === "assessment_supported" ? "assessment" : state === "extracted" ? "resume_extraction" : "self_report";
const sourceTypeFor = (state: string) =>
  state === "reviewer_confirmed" ? "performance_review" : state === "assessment_supported" ? "assessment" : "resume_document";

const SKILL_NAME = new Map<string, string>(DEMO_FIXTURES.skills.map((s) => [s.id, s.skill]));

/**
 * Structural seed-twin shape accepted by `twinRow`. Fixtures arrive as literal
 * (read-only) unions, so the parameter is widened to the fields twinRow reads —
 * not a hiding cast, just an explicit structural contract.
 */
interface TwinSeedRow {
  id: string;
  name: string;
  email: string;
  role: string;
  department: string | null;
  job_title: string | null;
  manager_id: string | null;
  tenure_months: number;
  seniority_level: number;
  promotion_lag_months: number | null;
  attendance: unknown;
  delivery: unknown;
  assertions?: readonly {
    readonly skill_id: string;
    readonly claimed_proficiency: number;
    readonly review_state: string;
  }[];
  interview_rubrics?: unknown;
  performance_history?: unknown;
  signals?: unknown;
  audit_events?: unknown;
}

function twinRow(p: TwinSeedRow, orgId: string, authIds: Record<string, string>, roleOverride?: string) {
  const role = roleOverride ?? p.role;
  return {
    id: p.id,
    org_id: orgId,
    auth_user_id: authIds[p.email] ?? null,
    role,
    status: role === "candidate" ? "candidate" : "active",
    name: p.name,
    email: p.email,
    department: p.department,
    job_title: p.job_title,
    manager_id: p.manager_id,
    tenure_months: p.tenure_months,
    seniority_level: p.seniority_level,
    promotion_lag_months: p.promotion_lag_months,
    attendance: p.attendance,
    delivery: p.delivery,
    verified_skills: (p.assertions ?? [])
      .filter((a) => a.review_state === "reviewer_confirmed" || a.review_state === "assessment_supported")
      .map((a) => ({
        name: SKILL_NAME.get(a.skill_id),
        proficiency: a.claimed_proficiency,
        evidence_source: sourceFor(a.review_state),
        verification_rigor: rigorFor(a.review_state),
      })),
    interview_rubrics: p.interview_rubrics ?? [],
    performance_history: p.performance_history ?? [],
    signals: p.signals ?? [],
    computed_fits: (SEED_FITS[p.id] ?? []) as unknown[],
    audit_events: p.audit_events ?? [],
  };
}

